mapper.update:
update edu_material_record
status = #{status}, del_flag = #{delFlag}, image_url = #{imageUrl}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
where record_id = #{recordId}

mapper.select:
SELECT item.item_id AS itemId, r.record_id AS recordId, r.record_no AS recordNo, r.record_type AS recordType, CASE r.record_type WHEN '1' THEN '发放领取' WHEN '2' THEN '退还回收' ELSE '其他' END AS recordTypeName, r.business_category AS businessCategory, r.operate_time AS operateTime, r.grade AS grade, COALESCE(r.class_name, (SELECT class_name FROM edu_class WHERE class_id = r.class_id), '通用公用') AS className, r.class_id AS classId, r.target_type AS targetType, CASE r.target_type WHEN '1' THEN '教师' WHEN '2' THEN '学生' WHEN '3' THEN '班级公用' ELSE '其他' END AS targetTypeName, r.target_name AS targetName, r.subject AS subject, g.category AS category, CASE g.category WHEN '1' THEN '教师办公品' WHEN '2' THEN '学生教材' WHEN '3' THEN '文印耗材' ELSE '其他物资' END AS categoryName, item.goods_id AS goodsId, COALESCE(item.goods_name, g.goods_name) AS goodsName, COALESCE(item.spec, g.spec, '-') AS spec, COALESCE(item.unit, g.unit, '件') AS unit, item.quantity AS quantity, COALESCE( (SELECT in_item.price FROM edu_stock_in_item in_item WHERE in_item.goods_id = item.goods_id ORDER BY in_item.item_id DESC LIMIT 1), 0.00 ) AS price, ROUND(item.quantity * COALESCE( (SELECT in_item.price FROM edu_stock_in_item in_item WHERE in_item.goods_id = item.goods_id ORDER BY in_item.item_id DESC LIMIT 1), 0.00 ), 2) AS amount, r.kit_name AS kitName, r.operator AS operator, item.item_status AS itemStatus, r.image_url AS imageUrl, r.remark AS remark FROM edu_material_record r JOIN edu_material_record_item item ON r.record_id = item.record_id LEFT JOIN edu_goods g ON item.goods_id = g.goods_id WHERE r.del_flag = '0' AND r.status = '0'
AND r.record_type = #{recordType}
AND r.business_category LIKE CONCAT('%', #{businessCategory}, '%')
AND r.target_type = #{targetType}
AND r.target_name LIKE CONCAT('%', #{targetName}, '%')
AND r.grade = #{grade}
AND r.class_id = #{classId}
AND (r.class_name LIKE CONCAT('%', #{className}, '%') OR (SELECT class_name FROM edu_class WHERE class_id = r.class_id) LIKE CONCAT('%', #{className}, '%'))
AND item.goods_id = #{goodsId}
AND (item.goods_name LIKE CONCAT('%', #{goodsName}, '%') OR g.goods_name LIKE CONCAT('%', #{goodsName}, '%'))
AND g.category = #{category}
AND r.operate_time >= #{beginTime}
AND r.operate_time <= #{endTime}
ORDER BY r.operate_time DESC, item.item_id DESC

SELECT COALESCE(r.class_id, 0) AS classId, COALESCE(r.grade, '全校通用') AS grade, COALESCE(MAX(r.class_name), (SELECT class_name FROM edu_class WHERE class_id = r.class_id), '通用公用') AS className, COUNT(DISTINCT r.record_id) AS orderCount, COALESCE(SUM(CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END), 0) AS totalQuantity, COUNT(DISTINCT item.goods_id) AS goodsTypesCount, COUNT(DISTINCT r.target_name) AS personCount, ROUND(COALESCE(SUM( (CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END) * COALESCE((SELECT in_item.price FROM edu_stock_in_item in_item WHERE in_item.goods_id = item.goods_id ORDER BY in_item.item_id DESC LIMIT 1), 0.00) ), 0), 2) AS totalAmount, GROUP_CONCAT(DISTINCT CONCAT(COALESCE(item.goods_name, g.goods_name), '*', item.quantity, COALESCE(item.unit, g.unit, '件')) SEPARATOR '；') AS goodsSummary FROM edu_material_record r JOIN edu_material_record_item item ON r.record_id = item.record_id LEFT JOIN edu_goods g ON item.goods_id = g.goods_id WHERE r.del_flag = '0' AND r.status = '0'
AND r.record_type = #{recordType}
AND r.business_category LIKE CONCAT('%', #{businessCategory}, '%')
AND r.target_type = #{targetType}
AND r.target_name LIKE CONCAT('%', #{targetName}, '%')
AND r.grade = #{grade}
AND r.class_id = #{classId}
AND (r.class_name LIKE CONCAT('%', #{className}, '%') OR (SELECT class_name FROM edu_class WHERE class_id = r.class_id) LIKE CONCAT('%', #{className}, '%'))
AND item.goods_id = #{goodsId}
AND (item.goods_name LIKE CONCAT('%', #{goodsName}, '%') OR g.goods_name LIKE CONCAT('%', #{goodsName}, '%'))
AND g.category = #{category}
AND r.operate_time >= #{beginTime}
AND r.operate_time <= #{endTime}
GROUP BY r.class_id, r.grade ORDER BY totalQuantity DESC

SELECT r.target_type AS targetType, CASE r.target_type WHEN '1' THEN '教师' WHEN '2' THEN '学生' WHEN '3' THEN '班级公用' ELSE '其他' END AS targetTypeName, r.target_name AS targetName, COALESCE(MAX(r.class_name), (SELECT class_name FROM edu_class WHERE class_id = MAX(r.class_id)), '-') AS className, MAX(r.grade) AS grade, MAX(r.subject) AS subject, COUNT(DISTINCT r.record_id) AS orderCount, COALESCE(SUM(CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END), 0) AS totalQuantity, COUNT(DISTINCT item.goods_id) AS goodsTypesCount, ROUND(COALESCE(SUM( (CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END) * COALESCE((SELECT in_item.price FROM edu_stock_in_item in_item WHERE in_item.goods_id = item.goods_id ORDER BY in_item.item_id DESC LIMIT 1), 0.00) ), 0), 2) AS totalAmount, GROUP_CONCAT(DISTINCT CONCAT(COALESCE(item.goods_name, g.goods_name), '*', item.quantity, COALESCE(item.unit, g.unit, '件')) SEPARATOR '；') AS goodsSummary FROM edu_material_record r JOIN edu_material_record_item item ON r.record_id = item.record_id LEFT JOIN edu_goods g ON item.goods_id = g.goods_id WHERE r.del_flag = '0' AND r.status = '0'
AND r.record_type = #{recordType}
AND r.business_category LIKE CONCAT('%', #{businessCategory}, '%')
AND r.target_type = #{targetType}
AND r.target_name LIKE CONCAT('%', #{targetName}, '%')
AND r.grade = #{grade}
AND r.class_id = #{classId}
AND (r.class_name LIKE CONCAT('%', #{className}, '%') OR (SELECT class_name FROM edu_class WHERE class_id = r.class_id) LIKE CONCAT('%', #{className}, '%'))
AND item.goods_id = #{goodsId}
AND (item.goods_name LIKE CONCAT('%', #{goodsName}, '%') OR g.goods_name LIKE CONCAT('%', #{goodsName}, '%'))
AND g.category = #{category}
AND r.operate_time >= #{beginTime}
AND r.operate_time <= #{endTime}
GROUP BY r.target_type, r.target_name ORDER BY totalQuantity DESC

SELECT 
    COALESCE(SUM(CASE WHEN r.record_type = '1' THEN item.quantity ELSE 0 END), 0) AS totalGrantQty,
    COALESCE(SUM(CASE WHEN r.record_type = '2' THEN item.quantity ELSE 0 END), 0) AS totalReturnQty,
    COALESCE(SUM(CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END), 0) AS netGrantQty,
    COUNT(DISTINCT r.target_name) AS totalPersonCount,
    COUNT(DISTINCT r.class_id) AS totalClassCount,
    COUNT(DISTINCT r.record_id) AS totalOrderCount,
    ROUND(COALESCE(SUM(
        (CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END) * 
        COALESCE((SELECT in_item.price FROM edu_stock_in_item in_item WHERE in_item.goods_id = item.goods_id ORDER BY in_item.item_id DESC LIMIT 1), 0.00)
    ), 0), 2) AS totalAmount
FROM edu_material_record r
JOIN edu_material_record_item item ON r.record_id = item.record_id
LEFT JOIN edu_goods g ON item.goods_id = g.goods_id
WHERE r.del_flag = '0' AND r.status = '0'

    AND r.record_type = #{recordType}


    AND r.business_category LIKE CONCAT('%', #{businessCategory}, '%')


    AND r.target_type = #{targetType}


    AND r.target_name LIKE CONCAT('%', #{targetName}, '%')


    AND r.grade = #{grade}


    AND r.class_id = #{classId}


    AND (r.class_name LIKE CONCAT('%', #{className}, '%') OR (SELECT class_name FROM edu_class WHERE class_id = r.class_id) LIKE CONCAT('%', #{className}, '%'))


    AND item.goods_id = #{goodsId}


    AND (item.goods_name LIKE CONCAT('%', #{goodsName}, '%') OR g.goods_name LIKE CONCAT('%', #{goodsName}, '%'))


    AND g.category = #{category}


    AND r.operate_time >= #{beginTime}


    AND r.operate_time <= #{endTime}

SELECT CASE g.category WHEN '1' THEN '教师办公品' WHEN '2' THEN '学生教材' WHEN '3' THEN '文印耗材' ELSE '其他物资' END AS name, COALESCE(SUM(item.quantity), 0) AS value FROM edu_material_record r JOIN edu_material_record_item item ON r.record_id = item.record_id LEFT JOIN edu_goods g ON item.goods_id = g.goods_id WHERE r.del_flag = '0' AND r.status = '0' AND r.record_type = '1'
AND r.business_category LIKE CONCAT('%', #{businessCategory}, '%')
AND r.target_type = #{targetType}
AND r.target_name LIKE CONCAT('%', #{targetName}, '%')
AND r.grade = #{grade}
AND r.class_id = #{classId}
AND (r.class_name LIKE CONCAT('%', #{className}, '%') OR (SELECT class_name FROM edu_class WHERE class_id = r.class_id) LIKE CONCAT('%', #{className}, '%'))
AND item.goods_id = #{goodsId}
AND (item.goods_name LIKE CONCAT('%', #{goodsName}, '%') OR g.goods_name LIKE CONCAT('%', #{goodsName}, '%'))
AND g.category = #{category}
AND r.operate_time >= #{beginTime}
AND r.operate_time <= #{endTime}
GROUP BY g.category ORDER BY value DESC

SELECT 
    COALESCE(MAX(r.class_name), (SELECT class_name FROM edu_class WHERE class_id = r.class_id), '通用公用') AS className,
    COALESCE(SUM(CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END), 0) AS quantity
FROM edu_material_record r
JOIN edu_material_record_item item ON r.record_id = item.record_id
LEFT JOIN edu_goods g ON item.goods_id = g.goods_id
WHERE r.del_flag = '0' AND r.status = '0'

    AND r.record_type = #{recordType}


    AND r.business_category LIKE CONCAT('%', #{businessCategory}, '%')


    AND r.target_type = #{targetType}


    AND r.target_name LIKE CONCAT('%', #{targetName}, '%')


    AND r.grade = #{grade}


    AND r.class_id = #{classId}


    AND (r.class_name LIKE CONCAT('%', #{className}, '%') OR (SELECT class_name FROM edu_class WHERE class_id = r.class_id) LIKE CONCAT('%', #{className}, '%'))


    AND item.goods_id = #{goodsId}


    AND (item.goods_name LIKE CONCAT('%', #{goodsName}, '%') OR g.goods_name LIKE CONCAT('%', #{goodsName}, '%'))


    AND g.category = #{category}


    AND r.operate_time >= #{beginTime}


    AND r.operate_time <= #{endTime}

GROUP BY r.class_id
ORDER BY quantity DESC
LIMIT 10

SELECT DATE_FORMAT(r.operate_time, '%Y-%m') AS month, COALESCE(SUM(CASE WHEN r.record_type = '1' THEN item.quantity ELSE 0 END), 0) AS grantQty, COALESCE(SUM(CASE WHEN r.record_type = '2' THEN item.quantity ELSE 0 END), 0) AS returnQty FROM edu_material_record r JOIN edu_material_record_item item ON r.record_id = item.record_id LEFT JOIN edu_goods g ON item.goods_id = g.goods_id WHERE r.del_flag = '0' AND r.status = '0'
AND r.business_category LIKE CONCAT('%', #{businessCategory}, '%')
AND r.target_type = #{targetType}
AND r.target_name LIKE CONCAT('%', #{targetName}, '%')
AND r.grade = #{grade}
AND r.class_id = #{classId}
AND (r.class_name LIKE CONCAT('%', #{className}, '%') OR (SELECT class_name FROM edu_class WHERE class_id = r.class_id) LIKE CONCAT('%', #{className}, '%'))
AND item.goods_id = #{goodsId}
AND (item.goods_name LIKE CONCAT('%', #{goodsName}, '%') OR g.goods_name LIKE CONCAT('%', #{goodsName}, '%'))
AND g.category = #{category}
AND DATE_FORMAT(r.operate_time, '%Y-%m') >= #{beginMonth}
GROUP BY month ORDER BY month ASC LIMIT 12

SELECT COALESCE(item.goods_name, g.goods_name) AS goodsName, COALESCE(item.unit, g.unit, '件') AS unit, COALESCE(SUM(item.quantity), 0) AS quantity, COUNT(DISTINCT r.target_name) AS personCount, COUNT(DISTINCT r.class_id) AS classCount FROM edu_material_record r JOIN edu_material_record_item item ON r.record_id = item.record_id LEFT JOIN edu_goods g ON item.goods_id = g.goods_id WHERE r.del_flag = '0' AND r.status = '0' AND r.record_type = '1'
AND r.target_type = #{targetType}
AND r.target_name LIKE CONCAT('%', #{targetName}, '%')
AND r.grade = #{grade}
AND r.class_id = #{classId}
AND (r.class_name LIKE CONCAT('%', #{className}, '%') OR (SELECT class_name FROM edu_class WHERE class_id = r.class_id) LIKE CONCAT('%', #{className}, '%'))
AND g.category = #{category}
AND r.operate_time >= #{beginTime}
AND r.operate_time <= #{endTime}
GROUP BY item.goods_id, goodsName, unit ORDER BY quantity DESC LIMIT 8

SELECT COALESCE(r.class_id, 0) AS classId, COALESCE(r.grade, '全校通用') AS grade, COALESCE(MAX(r.class_name), (SELECT class_name FROM edu_class WHERE class_id = r.class_id), '通用公用') AS className, item.goods_id AS goodsId, COALESCE(item.goods_name, g.goods_name) AS goodsName, COALESCE(item.spec, g.spec, '-') AS spec, COALESCE(item.unit, g.unit, '件') AS unit, CASE g.category WHEN '1' THEN '教师办公品' WHEN '2' THEN '学生教材' WHEN '3' THEN '文印耗材' ELSE '其他物资' END AS categoryName, COALESCE(SUM(CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END), 0) AS quantity, COALESCE((SELECT in_item.price FROM edu_stock_in_item in_item WHERE in_item.goods_id = item.goods_id ORDER BY in_item.item_id DESC LIMIT 1), 0.00) AS price, ROUND(COALESCE(SUM( (CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END) * COALESCE((SELECT in_item.price FROM edu_stock_in_item in_item WHERE in_item.goods_id = item.goods_id ORDER BY in_item.item_id DESC LIMIT 1), 0.00) ), 0), 2) AS amount FROM edu_material_record r JOIN edu_material_record_item item ON r.record_id = item.record_id LEFT JOIN edu_goods g ON item.goods_id = g.goods_id WHERE r.del_flag = '0' AND r.status = '0'
AND r.record_type = #{recordType}
AND r.business_category LIKE CONCAT('%', #{businessCategory}, '%')
AND r.target_type = #{targetType}
AND r.target_name LIKE CONCAT('%', #{targetName}, '%')
AND r.grade = #{grade}
AND r.class_id = #{classId}
AND (r.class_name LIKE CONCAT('%', #{className}, '%') OR (SELECT class_name FROM edu_class WHERE class_id = r.class_id) LIKE CONCAT('%', #{className}, '%'))
AND item.goods_id = #{goodsId}
AND (item.goods_name LIKE CONCAT('%', #{goodsName}, '%') OR g.goods_name LIKE CONCAT('%', #{goodsName}, '%'))
AND g.category = #{category}
AND r.operate_time >= #{beginTime}
AND r.operate_time <= #{endTime}
GROUP BY r.class_id, r.grade, item.goods_id, goodsName, spec, unit, categoryName ORDER BY r.class_id, quantity DESC

SELECT r.target_type AS targetType, CASE r.target_type WHEN '1' THEN '教师' WHEN '2' THEN '学生' WHEN '3' THEN '班级公用' ELSE '其他' END AS targetTypeName, r.target_name AS targetName, COALESCE(MAX(r.class_name), (SELECT class_name FROM edu_class WHERE class_id = MAX(r.class_id)), '-') AS className, MAX(r.grade) AS grade, MAX(r.subject) AS subject, item.goods_id AS goodsId, COALESCE(item.goods_name, g.goods_name) AS goodsName, COALESCE(item.spec, g.spec, '-') AS spec, COALESCE(item.unit, g.unit, '件') AS unit, CASE g.category WHEN '1' THEN '教师办公品' WHEN '2' THEN '学生教材' WHEN '3' THEN '文印耗材' ELSE '其他物资' END AS categoryName, COALESCE(SUM(CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END), 0) AS quantity, COALESCE((SELECT in_item.price FROM edu_stock_in_item in_item WHERE in_item.goods_id = item.goods_id ORDER BY in_item.item_id DESC LIMIT 1), 0.00) AS price, ROUND(COALESCE(SUM( (CASE WHEN r.record_type = '1' THEN item.quantity ELSE -item.quantity END) * COALESCE((SELECT in_item.price FROM edu_stock_in_item in_item WHERE in_item.goods_id = item.goods_id ORDER BY in_item.item_id DESC LIMIT 1), 0.00) ), 0), 2) AS amount FROM edu_material_record r JOIN edu_material_record_item item ON r.record_id = item.record_id LEFT JOIN edu_goods g ON item.goods_id = g.goods_id WHERE r.del_flag = '0' AND r.status = '0'
AND r.record_type = #{recordType}
AND r.business_category LIKE CONCAT('%', #{businessCategory}, '%')
AND r.target_type = #{targetType}
AND r.target_name LIKE CONCAT('%', #{targetName}, '%')
AND r.grade = #{grade}
AND r.class_id = #{classId}
AND (r.class_name LIKE CONCAT('%', #{className}, '%') OR (SELECT class_name FROM edu_class WHERE class_id = r.class_id) LIKE CONCAT('%', #{className}, '%'))
AND item.goods_id = #{goodsId}
AND (item.goods_name LIKE CONCAT('%', #{goodsName}, '%') OR g.goods_name LIKE CONCAT('%', #{goodsName}, '%'))
AND g.category = #{category}
AND r.operate_time >= #{beginTime}
AND r.operate_time <= #{endTime}
GROUP BY r.target_type, r.target_name, item.goods_id, goodsName, spec, unit, categoryName ORDER BY r.target_name, quantity DESC
